def parse_pairs(lines):
    result = {}
    for line in lines:
        if not line.strip():
            continue

        if '=' not in line:
            raise ValueError("Missing '='")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key:
            raise ValueError("Empty key")

        result[key] = value
    return result

def run_tests():
    # Test basic functionality
    assert parse_pairs(["a=b", "c=d"]) == {"a": "b", "c": "d"}

    # Test blank lines
    assert parse_pairs(["a=b", "  ", "\n", "c=d"]) == {"a": "b", "c": "d"}

    # Test whitespace stripping
    assert parse_pairs(["  key  =  value  "]) == {"key": "value"}

    # Test preserve '=' in values
    assert parse_pairs(["key=val=ue"]) == {"key": "val=ue"}

    # Test duplicate keys (later wins)
    assert parse_pairs(["a=1", "a=2"]) == {"a": "2"}

    # Test missing '='
    try:
        parse_pairs(["invalid_line"])
        assert False, "Should have raised ValueError for missing '='"
    except ValueError:
        pass

    # Test empty key
    try:
        parse_pairs(["=value"])
        assert False, "Should have raised ValueError for empty key"
    except ValueError:
        pass

    # Test do not mutate input
    input_lines = ["a=b", "c=d"]
    parse_pairs(input_lines)
    assert input_lines == ["a=b", "c=d"]

run_tests()

