def merge_tool_results(calls, results):
    # The tests show that 'calls' is a LIST of dicts, not a dict.
    # "calls and results are dicts with an id" likely meant "collections of dicts".
    # Let's re-read: "calls and results are dicts with an id". 
    # If calls is a list, then calls[0] is a dict.

    # 1. Validate calls for duplicate ids
    seen_ids = set()
    for c in calls:
        cid = c.get('id')
        if cid in seen_ids:
            raise ValueError(f"Duplicate call id: {cid}")
        seen_ids.add(cid)

    # 2. Process results (last one wins)
    # results is a list of dicts
    res_map = {}
    for r in results:
        rid = r.get('id')
        if rid in seen_ids:
            res_map[rid] = r

    # 3. Build output in call order
    output = []
    for c in calls:
        cid = c.get('id')
        if cid in res_map:
            output.append({
                'id': cid,
                'status': 'done',
                'content': res_map[cid].get('content', '')
            })
        else:
            output.append({
                'id': cid,
                'status': 'pending'
            })
    return output

