    # Test case 1: Basic functionality
    calls = {
        'a': {'id': 1, 'param': 'x'},
        'b': {'id': 2, 'param': 'y'},
        'c': {'id': 3, 'param': 'z'}
    }
    results = [
        {'id': 1, 'content': 'res1'},
        {'id': 2, 'content': 'res2'}
    ]
    expected = [
        {'id': 1, 'status': 'done', 'content': 'res1'},
        {'id': 2, 'status': 'done', 'content': 'res2'},
        {'id': 3, 'status': 'pending'}
    ]
    assert merge_tool_results(calls, results) == expected

    # Test case 2: Last result wins
    results = [
        {'id': 1, 'content': 'res1_old'},
        {'id': 1, 'content': 'res1_new'},
        {'id': 2, 'content': 'res2'}
    ]
    expected = [
        {'id': 1, 'status': 'done', 'content': 'res1_new'},
        {'id': 2, 'status': 'done', 'content': 'res2'},
        {'id': 3, 'status': 'pending'}
