        {'id': 99, 'content': 'unknown'}
    ]
    expected = [
        {'id': 1, 'status': 'done', 'content': 'res1'},
        {'id': 2, 'status': 'pending'},
        {'id': 3, 'status': 'pending'}
    ]
    assert merge_tool_results(calls, results) == expected

    # Test case 5: Duplicate call ids raise ValueError
    calls_dup = {
        'a': {'id': 1},
        'b': {'id': 1}
    }
    try:
        merge_tool_results(calls_dup, [])
        assert False, "Should have raised ValueError"
    except ValueError:
        pass

    # Test case 6: Do not mutate inputs
    calls_orig = {'a': {'id': 1}}
    results_orig = [{'id': 1, 'content': 'res1'}]
    calls_copy = {'a': {'id': 1}}
    results_copy = [{'id': 1, 'content': 'res1'}]
    merge_tool_results(calls_orig, results_orig)
    assert calls_orig == calls_copy
    assert results_orig == results_copy

