def trim_history(messages, budget):
    if budget < 0:
        raise ValueError("Budget must be non-negative")

    costs = []
    for msg in messages:
        # The prompt says "Each message is a dict with integer cost".
        # It doesn't explicitly say 'cost' is the only key.
        # It says "Each message is a dict with integer cost".
        # Let's assume 'cost' is the key.
        c = msg['cost']
        if not isinstance(c, int) or c < 0:
            raise ValueError("Message cost must be a non-negative integer")
        costs.append(c)

    n = len(messages)
