def merge_tool_results(calls, results):
    # Check for duplicate call ids
    call_ids = []
    for call_id in calls:
        if call_id in call_ids:
            raise ValueError(f"Duplicate call id: {call_id}")
        call_ids.append(call_id)

    # Create a mapping of result id to its content
    # The last result for an id wins
    result_map = {}
    for res_id, res_content in results.items():
        result_map[res_id] = res_content

    merged = []
    for call_id in call_ids:
        if call_id in result_map:
            content = result_map[call_id]
            if content is None:
                content = ''
            merged.append({'id': call_id, 'status': 'done', 'content': content})
        else:
            merged.append({'id': call_id, 'status': 'pending'})

    return merged

