def summarize_usage(events):
    request_max_input = {}
    request_max_output = {}

    for event in events:
        req_id = event.get('request_id')
        if req_id is None:
            continue

        in_count = event.get('input')
        out_count = event.get('output')

        if in_count is not None:
            if in_count < 0:
                raise ValueError("Negative input count")
            request_max_input[req_id] = max(request_max_input.get(req_id, 0), in_count)

        if out_count is not None:
            if out_count < 0:
                raise ValueError("Negative output count")
            request_max_output[req_id] = max(request_max_output.get(req_id, 0), out_count)

    total_input = sum(request_max_input.values())
    total_output = sum(request_max_output.values())

    return {'input': total_input, 'output': total_output}

